:root {
  --bg: #1a1a2e;
  --surface: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --card-back: #533483;
  --card-back-hover: #6a4c9c;
  --focus: #f9c74f;
  --radius: 10px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  max-width: 640px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.game-header {
  text-align: center;
  margin-bottom: 20px;
}

h1 {
  font-size: 1.6rem;
  color: var(--primary);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 1rem;
  opacity: 0.8;
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  gap: 12px;
  flex-wrap: wrap;
}

.moves {
  font-size: 1.1rem;
  font-weight: 600;
}

#newGameBtn {
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 20px;
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

#newGameBtn:hover {
  background: #ff5a75;
}

#newGameBtn:active {
  transform: scale(0.96);
}

#newGameBtn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 20px;
}

.card {
  aspect-ratio: 1;
  border: none;
  border-radius: var(--radius);
  background: var(--card-back);
  cursor: pointer;
  font-size: 1.5rem;
  color: transparent;
  transition: background 0.2s, transform 0.15s;
  position: relative;
  overflow: hidden;
}

.card:hover:not(.matched):not(.flipped) {
  background: var(--card-back-hover);
}

.card:active:not(.matched):not(.flipped) {
  transform: scale(0.95);
}

.card:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.card.flipped,
.card.matched {
  background: var(--secondary);
  color: #fff;
  cursor: default;
}

.card.matched {
  opacity: 0.7;
}

.card.flipped .card-icon,
.card.matched .card-icon {
  display: block;
}

.card-icon {
  display: none;
  width: 100%;
  height: 100%;
  position: absolute;
  inset: 0;
  border-radius: var(--radius);
}

.win-message {
  text-align: center;
  padding: 16px;
  background: var(--secondary);
  border-radius: var(--radius);
  font-size: 1.2rem;
  font-weight: 600;
}

.win-message p + p {
  margin-top: 8px;
  font-size: 1rem;
  font-weight: 400;
}

@media (max-width: 480px) {
  body {
    font-size: 16px;
    padding: 8px;
  }

  .game-container {
    padding: 16px;
  }

  h1 {
    font-size: 1.3rem;
  }

  .game-board {
    gap: 8px;
  }

  #newGameBtn {
    padding: 8px 16px;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e94560', '#f9c74f', '#43aa8b', '#577590',
    '#f8961e', '#9b5de5', '#00bbf9', '#f15bb5'
  ];

  const boardEl = document.getElementById('gameBoard');
  const moveCountEl = document.getElementById('moveCount');
  const winMessageEl = document.getElementById('winMessage');
  const finalMovesEl = document.getElementById('finalMoves');
  const newGameBtn = document.getElementById('newGameBtn');

  let cards = [];
  let firstCard = null;
  let secondCard = null;
  let lockBoard = false;
  let moves = 0;
  let matchedPairs = 0;

  function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  function createDeck() {
    const deck = [];
    COLORS.forEach((color, index) => {
      deck.push({ color, pairId: index });
      deck.push({ color, pairId: index });
    });
    return shuffle(deck);
  }

  function createCardElement(card, index) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'card';
    btn.dataset.pairId = card.pairId;
    btn.dataset.index = index;
    btn.setAttribute('aria-label', 'Hidden card ' + (index + 1));
    btn.setAttribute('role', 'gridcell');

    const icon = document.createElement('span');
    icon.className = 'card-icon';
    icon.style.background = card.color;
    btn.appendChild(icon);

    btn.addEventListener('click', onCardClick);
    return btn;
  }

  function renderBoard() {
    boardEl.innerHTML = '';
    cards.forEach((card, index) => {
      boardEl.appendChild(createCardElement(card, index));
    });
  }

  function onCardClick(e) {
    const cardEl = e.currentTarget;
    if (lockBoard) return;
    if (cardEl.classList.contains('flipped') || cardEl.classList.contains('matched')) return;

    flipCard(cardEl);

    if (!firstCard) {
      firstCard = cardEl;
      return;
    }

    secondCard = cardEl;
    moves++;
    moveCountEl.textContent = moves;
    checkMatch();
  }

  function flipCard(cardEl) {
    cardEl.classList.add('flipped');
    cardEl.setAttribute('aria-label', 'Card ' + (parseInt(cardEl.dataset.index, 10) + 1) + ' revealed');
  }

  function unflipCard(cardEl) {
    cardEl.classList.remove('flipped');
    cardEl.setAttribute('aria-label', 'Hidden card ' + (parseInt(cardEl.dataset.index, 10) + 1));
  }

  function checkMatch() {
    const isMatch = firstCard.dataset.pairId === secondCard.dataset.pairId;

    if (isMatch) {
      firstCard.classList.add('matched');
      secondCard.classList.add('matched');
      firstCard.setAttribute('aria-label', 'Matched pair');
      secondCard.setAttribute('aria-label', 'Matched pair');
      matchedPairs++;
      resetTurn();

      if (matchedPairs === COLORS.length) {
        showWin();
      }
    } else {
      lockBoard = true;
      setTimeout(() => {
        unflipCard(firstCard);
        unflipCard(secondCard);
        resetTurn();
      }, 800);
    }
  }

  function resetTurn() {
    firstCard = null;
    secondCard = null;
    lockBoard = false;
  }

  function showWin() {
    finalMovesEl.textContent = moves;
    winMessageEl.hidden = false;
  }

  function startGame() {
    cards = createDeck();
    firstCard = null;
    secondCard = null;
    lockBoard = false;
    moves = 0;
    matchedPairs = 0;
    moveCountEl.textContent = '0';
    winMessageEl.hidden = true;
    renderBoard();
  }

  newGameBtn.addEventListener('click', startGame);

  startGame();
})();
